#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t; cin >> t;    while(t--) {        int n; cin >> n;        vector<long long> s(n);        for(auto &x : s) cin >> x;         vector<int> p(n);         for(int i = 0; i < n; ) {            int j = i;             // find group of equal values            while(j < n && s[j] == s[i]) j++;             int len = j - i;             // if group size = 1 → impossible            if(len == 1) {                cout << -1 << '\n';                goto next;            }             // rotate within group            for(int k = i; k < j; k++) {                if(k == j - 1)                    p[k] = i + 1;     // last → first                else                    p[k] = k + 2;     // shift right            }             i = j;        }         // print answer        for(int i = 0; i < n; i++) {            cout << p[i] << " ";        }        cout << '\n';         next:;    }}